prompt --application/shared_components/navigation/lists/mms_notification_list
begin
wwv_flow_imp_shared.create_list(
 p_id=>wwv_flow_imp.id(422753330491190791)
,p_name=>'MMS_NOTIFICATION_LIST'
,p_list_type=>'SQL_QUERY'
,p_list_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    1 AS LEVEL_NO,',
'    ''Notification ('' ||',
'        CASE',
'            WHEN UPPER(:APP_USER) = ''AMIR''',
'            THEN (',
'                SELECT COUNT(*)',
'                FROM MS_COMPLAINT_H',
'                WHERE UPPER(TRIM(STATUS_CODE)) = ''SUBMITTED''',
'            )',
'            ELSE 0',
'        END',
'    || '')'' AS LABEL,',
'    ''f?p='' || :APP_ID || '':3:'' || :APP_SESSION AS TARGET,',
'    ''NO'' AS IS_CURRENT,',
'    ''fa-bell'' AS ICON',
'FROM DUAL'))
,p_list_status=>'PUBLIC'
);
end;
