prompt --application/shared_components/logic/application_processes/set_submitted_count
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(422768625006286736)
,p_process_sequence=>1
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_SUBMITTED_COUNT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_count NUMBER := 0;',
'BEGIN',
'    SELECT COUNT(*)',
'      INTO l_count',
'      FROM MS_COMPLAINT_H',
'     WHERE UPPER(TRIM(STATUS_CODE)) = ''SUBMITTED'';',
'',
'    IF l_count > 0 THEN',
'        :G_SUBMITTED_COUNT := TO_CHAR(l_count);',
'    ELSE',
'        :G_SUBMITTED_COUNT := NULL;',
'    END IF;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        :G_SUBMITTED_COUNT := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>5988357884178
);
end;
/
