prompt --application/shared_components/user_interface/lovs/inventory_item_id
begin
wwv_flow_imp_shared.create_list_of_values(
 p_id=>wwv_flow_imp.id(418104969082845681)
,p_lov_name=>'INVENTORY_ITEM_ID'
,p_lov_query=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT UNIQUE MSI.INVENTORY_ITEM_ID,MSI.CONCATENATED_SEGMENTS ITEM_CODE,MSI.DESCRIPTION ITEM_DESCRIPTION,MSI.PRIMARY_UOM_CODE UOM ,SUM(MOQ.TRANSACTION_QUANTITY) STOCK_QTY,',
'                ROUND((SELECT ITEM_COST',
'                         FROM CST_QUANTITY_LAYERS@PRODDB CQL',
'                         WHERE CQL.INVENTORY_ITEM_ID = MOQ.INVENTORY_ITEM_ID',
'                         AND CQL.ORGANIZATION_ID = MOQ.ORGANIZATION_ID',
'                ),0) ITEM_RATE',
'FROM MTL_ONHAND_QUANTITIES@PRODDB MOQ,MTL_SYSTEM_ITEMS_KFV@PRODDB MSI',
'WHERE 1=1',
'AND MOQ.INVENTORY_ITEM_ID = MSI.INVENTORY_ITEM_ID',
'AND MOQ.ORGANIZATION_ID = MSI.ORGANIZATION_ID',
'--AND MOQ.INVENTORY_ITEM_ID = 6837434',
'and msi.segment1 in (800,810,830)',
'AND MOQ.ORGANIZATION_ID = ''91''',
'GROUP BY MSI.INVENTORY_ITEM_ID,MSI.CONCATENATED_SEGMENTS ,MSI.DESCRIPTION ,MSI.PRIMARY_UOM_CODE, MOQ.INVENTORY_ITEM_ID,MOQ.ORGANIZATION_ID;'))
,p_source_type=>'SQL'
,p_location=>'LOCAL'
,p_use_local_sync_table=>false
,p_query_owner=>'APP'
,p_return_column_name=>'ITEM_DESCRIPTION'
,p_display_column_name=>'ITEM_DESCRIPTION'
,p_group_sort_direction=>'ASC'
,p_default_sort_column_name=>'ITEM_DESCRIPTION'
