,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function ehSelectHall(pHallId) {',
'    apex.item(''P1_HALL_ID'').setValue(pHallId);',
'    apex.item(''P1_MACHINE_ID'').setValue('''');   // hall badle to machine reset',
'    apex.region(''eh_dashboard'').refresh();',
'}',
'',
'function ehSelectMachine(pMachineId) {',
'    apex.item(''P1_MACHINE_ID'').setValue(pMachineId);',
'    apex.region(''eh_dashboard'').refresh();',
'}',
'',
'function ehRegisterComplaint(pFaultId) {',
'    apex.message.confirm(''Is fault par complaint register karni hai?'', function (ok) {',
'        if (!ok) return;',
'        apex.server.process(''REGISTER_COMPLAINT'', {',
'            x01: apex.item(''P1_HALL_ID'').getValue(),',
'            x02: apex.item(''P1_MACHINE_ID'').getValue(),',
'            x03: pFaultId',
'        }, {',
'            dataType: ''json'',',
'            success: function (d) {',
'                if (d.success) {',
'                    apex.message.showPageSuccess(''Complaint registered. ID: '' + d.complaint_id);',
'                } else {',
'                    apex.message.alert(''Error: '' + d.message);',
'                }',
'            }',
'        });',
'    });',
'}'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.hall-list {',
'    display: grid;',
'    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));',
'    gap: 12px;',
'}',
'',
'.hall-card {',
'    padding: 16px;',
'    background: #f4f7fb;',
'    border: 1px solid #d8e2ef;',
'    border-radius: 8px;',
'    font-weight: 600;',
'    color: #efefef;',
'}',
''))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'13'
,p_last_updated_by=>'AMIR'
,p_last_upd_yyyymmddhh24miss=>'20261105152122'
