,p_attribute_01=>'N'
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(406114249917433524)
,p_name=>'P1_MACHINE_ID'
,p_item_sequence=>40
,p_display_as=>'NATIVE_HIDDEN'
,p_attribute_01=>'N'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(406114343985433525)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'REGISTER_COMPLAINT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_hall_id    NUMBER := TO_NUMBER(apex_application.g_x01);',
'    l_machine_id NUMBER := TO_NUMBER(apex_application.g_x02);',
'    l_mfault_id  NUMBER := TO_NUMBER(apex_application.g_x03);',
'    l_token      VARCHAR2(100) := apex_application.g_x04;',
'',
'    l_line_id    EM_MACHINES.LINE_ID%TYPE;',
'    l_fault_id   NUMBER;',
'    l_fault_desc VARCHAR2(4000);',
'    l_complaint_id MS_COMPLAINT_H.COMPLAINT_ID%TYPE;',
'BEGIN',
'    -- Double click / duplicate submit check',
'    BEGIN',
'        SELECT COMPLAINT_ID INTO l_complaint_id',
'          FROM MS_COMPLAINT_H',
'         WHERE REQUEST_TOKEN = l_token;',
'    EXCEPTION WHEN NO_DATA_FOUND THEN',
'        l_complaint_id := NULL;',
'    END;',
'',
'    IF l_complaint_id IS NULL THEN',
'        -- Machine + fault details nikalo (client se trust nahi, DB se lo)',
'        SELECT M.LINE_ID, F.MACHINE_FAULT_ID, F.FAULT_DESCRIPTION',
'          INTO l_line_id, l_fault_id, l_fault_desc',
'          FROM EM_MACHINE_FAULTS F',
'          JOIN EM_MACHINES M ON M.MACHINE_ID = F.MACHINE_ID',
'         WHERE F.MACHINE_FAULT_ID = l_mfault_id',
'           AND M.MACHINE_ID       = l_machine_id',
'           AND M.HALL_ID          = l_hall_id;',
'',
'        INSERT INTO MS_COMPLAINT_H',
'            (COMPLAINT_DATE, REPORTED_BY, LINE_ID, MACHINE_ID, LOCATION_ID,',
'             FAULT_ID, FAULT_DESCRIPTION, STATUS_CODE, REPORTED_DATE_TIME,',
'             REQUEST_TOKEN, CREATED_BY, CREATED_DATE)',
'        VALUES',
'            (TRUNC(SYSDATE), :APP_USER, l_line_id, l_machine_id, l_hall_id,',
'             l_fault_id, l_fault_desc, ''OPEN'', SYSDATE,',
'             l_token, :APP_USER, SYSDATE)',
'        RETURNING COMPLAINT_ID INTO l_complaint_id;',
'',
'        COMMIT;',
'    END IF;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', TRUE);',
'    apex_json.write(''complaint_id'', l_complaint_id);',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        ROLLBACK;',
'        apex_json.open_object;',
'        apex_json.write(''success'', FALSE);',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>406114343985433525
);
end;
