'.status-badge {',
'    padding: 6px 14px;',
'    border-radius: 15px;',
'    font-weight: bold;',
'    display: inline-block;',
'    text-align: center;',
'    min-width: 110px;',
'    font-size: 12px;',
'    border: 1px solid transparent;',
'}',
'',
'/* SUBMITTED - Dark Grey */',
'.status-badge.Submitted {',
'    background-color: #9CA3AF;',
'    color: #111827;',
'    border-color: #6B7280;',
'}',
'',
'/* ACKNOWLEDGED - Dark Blue */',
'.status-badge.ACKNOWLEDGED {',
'    background-color: #93C5FD;',
'    color: #1E3A8A;',
'    border-color: #3B82F6;',
'}',
'',
'/* IN PROGRESS - Dark Orange */',
'.status-badge.IN_PROGRESS {',
'    background-color: #FBBF24;',
'    color: #78350F;',
'    border-color: #D97706;',
'}',
'',
'/* CLOSED - Dark Green */',
'.status-badge.CLOSED {',
'    background-color: #86EFAC;',
'    color: #14532D;',
'    border-color: #22C55E;',
'}',
'',
'/* CANCELLED - Dark Red */',
'.status-badge.CANCELLED {',
'    background-color: #FCA5A5;',
'    color: #7F1D1D;',
'    border-color: #DC2626;',
'}',
'/* REJECTED */',
'.status-badge.REJECTED {',
'    background-color: #F87171;',
'    color: #7F1D1D;',
'}',
'',
'/* ON_HOLD */',
'.status-badge.ON_HOLD {',
'    background-color: #C4B5FD;',
'    color: #4C1D95;',
'}',
'',
'/* RESOLVED */',
'.status-badge.RESOLVED {',
'    background-color: #67E8F9;',
'    color: #164E63;',
'}',
'',
'/* ------------------------------------------- */',
'/* =========================================================',
unistr('   COMPLAINT INTERACTIVE REPORT \2014 V2 (ADVANCED)'),
'   Region Static ID: COMPLAINT_IR',
'   Ye file purani complaint_ir.css ki jagah lagao (dono mat rakho).',
unistr('   Query / badge classes wohi hain \2014 query change nahi karni.'),
'   ========================================================= */',
'',
'#COMPLAINT_IR {',
'    --ink:#0b1220; --ink-2:#334155; --muted:#64748b;',
'    --line:#e6ecf3; --line-2:#d5dde8;',
'    --brand:#1f5f9f; --brand-2:#2b7bc9; --brand-deep:#123a63;',
'    --surface:#ffffff; --surface-2:#f6f9fc;',
'    --ring:0 0 0 4px rgba(31,95,159,.14);',
'    position:relative;',
'    background:var(--surface);',
'    border:1px solid var(--line);',
'    border-radius:18px;',
'    box-shadow:',
'        0 1px 2px rgba(11,18,32,.04),',
'        0 12px 32px -12px rgba(11,18,32,.18);',
'    overflow:hidden;',
'    animation:cirIn .45s cubic-bezier(.2,.8,.2,1) both;',
'}',
'',
'/* top glowing strip */',
'#COMPLAINT_IR::before {',
'    content:""; position:absolute; inset:0 0 auto 0; height:4px; z-index:3;',
'    background:linear-gradient(90deg,#1f5f9f,#2b7bc9,#38bdf8,#2b7bc9,#1f5f9f);',
'    background-size:200% 100%;',
'    animation:cirFlow 6s linear infinite;',
'}',
'',
'/* ---------- region header ---------- */',
'#COMPLAINT_IR > .t-Region-header {',
'    padding:20px 24px 16px;',
'    background: radial-gradient(600px 120px at 0% 0%, rgba(43,123,201,.10), transparent 70%),',
'                linear-gradient(180deg,#fff 0%,#f7fafd 100%);',
'    border-bottom:1px solid var(--line);',
'}',
'#COMPLAINT_IR .t-Region-title {',
'    font-size:19px; font-weight:800; letter-spacing:.2px; color:var(--ink);',
'    display:inline-flex; align-items:center; gap:10px;',
'}',
'#COMPLAINT_IR .t-Region-title::before {',
'    content:""; width:10px; height:10px; border-radius:50%;',
'    background:#22c55e; box-shadow:0 0 0 4px rgba(34,197,94,.18);',
'    animation:cirLive 1.8s ease-in-out infinite;',
'}',
'',
'/* ---------- toolbar / search ---------- */',
'#COMPLAINT_IR .a-IRR-toolbar {',
'    padding:14px 20px;',
'    background:var(--surface-2);',
'    border-bottom:1px solid var(--line);',
'    display:flex; align-items:center; gap:10px; flex-wrap:wrap;',
'}',
'#COMPLAINT_IR .a-IRR-searchField,',
'#COMPLAINT_IR .a-IRR-toolbar input[type="text"] {',
'    min-width:220px;',
'    padding:9px 14px 9px 36px;',
'    font-size:13px; color:var(--ink);',
'    border:1px solid var(--line-2); border-radius:999px;',
'    box-shadow:0 1px 2px rgba(11,18,32,.04);',
'    transition:border-color .18s, box-shadow .18s, min-width .25s;',
'}',
'#COMPLAINT_IR .a-IRR-searchField:focus,',
'#COMPLAINT_IR .a-IRR-toolbar input[type="text"]:focus {',
'    outline:none; border-color:var(--brand); box-shadow:var(--ring); min-width:300px;',
'}',
'/* toolbar buttons (Actions, Go, etc.) */',
'#COMPLAINT_IR .a-IRR-toolbar .a-Button,',
'#COMPLAINT_IR .a-IRR-toolbar button {',
'    border-radius:999px; font-weight:600; font-size:12.5px;',
'    padding:8px 16px; border:1px solid var(--line-2);',
'    background:#fff; color:var(--ink-2);',
'    transition:transform .15s, box-shadow .15s, background-color .15s;',
'}',
'#COMPLAINT_IR .a-IRR-toolbar .a-Button:hover,',
'#COMPLAINT_IR .a-IRR-toolbar button:hover {',
'    background:#f1f6fc; transform:translateY(-1px);',
'    box-shadow:0 4px 10px -4px rgba(11,18,32,.18);',
'}',
'',
'/* ---------- table container (scroll + sticky header) ---------- */',
'#COMPLAINT_IR .a-IRR-tableContainer,',
'#COMPLAINT_IR .a-IRR-tableContainer .a-IRR-tableWrap {',
'    max-height:68vh; overflow:auto;',
'}',
'#COMPLAINT_IR .a-IRR-tableContainer::-webkit-scrollbar { width:10px; height:10px; }',
'#COMPLAINT_IR .a-IRR-tableContainer::-webkit-scrollbar-track { background:#f1f5f9; }',
'#COMPLAINT_IR .a-IRR-tableContainer::-webkit-scrollbar-thumb {',
'    background:linear-gradient(180deg,#9db8d6,#7c9cc0);',
'    border-radius:10px; border:2px solid #f1f5f9;',
'}',
'',
'#COMPLAINT_IR .a-IRR-table { border-collapse:separate; border-spacing:0; width:100%; }',
'',
'/* header */',
'#COMPLAINT_IR .a-IRR-header {',
'    position:sticky; top:0; z-index:2;',
'    background:linear-gradient(180deg,var(--brand) 0%,var(--brand-deep) 100%);',
'    color:#fff; font-size:11px; font-weight:800;',
'    letter-spacing:.7px; text-transform:uppercase;',
'    padding:14px 12px; border:0; white-space:nowrap;',
'    box-shadow:inset 0 -1px 0 rgba(255,255,255,.12);',
'}',
'#COMPLAINT_IR .a-IRR-header a,',
'#COMPLAINT_IR .a-IRR-headerLink { color:#fff !important; text-decoration:none; }',
'#COMPLAINT_IR .a-IRR-header:hover { background:linear-gradient(180deg,#2b7bc9 0%,#17497a 100%); }',
'#COMPLAINT_IR .a-IRR-header:first-child { border-top-left-radius:0; }',
'',
'/* ---------- rows ---------- */',
'#COMPLAINT_IR .a-IRR-table td {',
'    padding:13px 12px; font-size:13px; color:var(--ink);',
'    background:#fff; border-bottom:1px solid #eef2f7;',
'    vertical-align:middle;',
'    transition:background-color .15s ease;',
'}',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(even) td { background:#fbfdff; }',
'#COMPLAINT_IR .a-IRR-table tbody tr:hover td { background:#eaf3fc; }',
'',
'/* row entrance */',
'#COMPLAINT_IR .a-IRR-table tbody tr { animation:cirRow .4s ease both; }',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(1){animation-delay:.02s}',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(2){animation-delay:.05s}',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(3){animation-delay:.08s}',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(4){animation-delay:.11s}',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(5){animation-delay:.14s}',
'#COMPLAINT_IR .a-IRR-table tbody tr:nth-child(n+6){animation-delay:.17s}',
'',
'/* PRIORITY ke hisaab se row ke left par color bar (modern browsers: :has) */',
'#COMPLAINT_IR .a-IRR-table tbody tr td:first-child { box-shadow:inset 4px 0 0 transparent; }',
'#COMPLAINT_IR .a-IRR-table tbody tr:has(.prio-critical) td:first-child { box-shadow:inset 4px 0 0 #dc2626; }',
'#COMPLAINT_IR .a-IRR-table tbody tr:has(.prio-high)     td:first-child { box-shadow:inset 4px 0 0 #ea580c; }',
'#COMPLAINT_IR .a-IRR-table tbody tr:has(.prio-medium)   td:first-child { box-shadow:inset 4px 0 0 #d97706; }',
'#COMPLAINT_IR .a-IRR-table tbody tr:has(.prio-low)      td:first-child { box-shadow:inset 4px 0 0 #16a34a; }',
'',
'/* machine STOPPED wali row halki laal */',
'#COMPLAINT_IR .a-IRR-table tbody tr:has(.ms-stopped) td { background-image:linear-gradient(90deg,rgba(254,226,226,.45),rgba(254,226,226,0) 60%); }',
'',
'/* complaint no */',
'#COMPLAINT_IR td[headers="COMPLAINT_NO"] {',
'    font-weight:800; color:var(--brand); letter-spacing:.3px;',
'    font-variant-numeric:tabular-nums;',
'}',
'/* numbers (downtime, reopen) */',
'#COMPLAINT_IR td[headers="DOWNTIME_MINUTES"],',
'#COMPLAINT_IR td[headers="REOPEN_COUNT"] {',
'    font-variant-numeric:tabular-nums; font-weight:600; color:var(--ink-2);',
'}',
'/* dates thori halki */',
'#COMPLAINT_IR td[headers$="DATE"],',
'#COMPLAINT_IR td[headers$="DATE_TIME"] { color:var(--muted); font-size:12px; white-space:nowrap; }',
'',
'/* long text clamp (description / reason) */',
'#COMPLAINT_IR td[headers="FAULT_DESCRIPTION"],',
'#COMPLAINT_IR td[headers="PRODUCTION_IMPACT"],',
'#COMPLAINT_IR td[headers="REJECTION_REASON"] {',
'    max-width:260px; line-height:1.45;',
'    display:table-cell;',
'}',
'',
'/* empty state */',
'#COMPLAINT_IR .a-IRR-noDataMsg,',
'#COMPLAINT_IR .nodatafound {',
'    padding:48px 20px; text-align:center; color:var(--muted);',
'    font-size:14px; font-weight:600;',
'}',
'',
'/* ---------- pagination ---------- */',
'#COMPLAINT_IR .a-IRR-pagination,',
'#COMPLAINT_IR .a-IRR-paginationWrap {',
'    padding:12px 20px; background:var(--surface-2); border-top:1px solid var(--line);',
'}',
'#COMPLAINT_IR .a-IRR-pagination-label { color:var(--muted); font-size:12px; font-weight:600; }',
'',
'/* =========================================================',
'   BADGES',
'   ========================================================= */',
'.cmp-badge {',
'    display:inline-flex; align-items:center; gap:7px;',
'    padding:5px 12px; border-radius:999px;',
'    font-size:10.5px; font-weight:800; letter-spacing:.5px;',
'    text-transform:uppercase; white-space:nowrap; line-height:1.3;',
'    border:1px solid transparent;',
'    box-shadow:0 1px 2px rgba(11,18,32,.06);',
'    transition:transform .15s ease, box-shadow .15s ease;',
'}',
'tr:hover .cmp-badge { transform:translateY(-1px); box-shadow:0 4px 10px -4px rgba(11,18,32,.25); }',
'',
'.cmp-dot { width:7px; height:7px; border-radius:50%; background:currentColor; display:inline-block; }',
'',
unistr('/* priority \2014 gradient + glow */'),
'.cmp-badge.prio-critical { background:linear-gradient(180deg,#fff1f1,#fee2e2); color:#b91c1c; border-color:#fca5a5; box-shadow:0 0 0 3px rgba(220,38,38,.08); }',
'.cmp-badge.prio-high     { background:linear-gradient(180deg,#fff7ed,#ffedd5); color:#c2410c; border-color:#fdba74; }',
'.cmp-badge.prio-medium   { background:linear-gradient(180deg,#fffbeb,#fef3c7); color:#b45309; border-color:#fcd34d; }',
'.cmp-badge.prio-low      { background:linear-gradient(180deg,#f0fdf4,#dcfce7); color:#15803d; border-color:#86efac; }',
'.cmp-badge.prio-none     { background:#f1f5f9; color:#64748b; border-color:#e2e8f0; }',
'.cmp-badge.prio-critical::before {',
'    content:""; width:7px; height:7px; border-radius:50%; background:#dc2626;',
'    animation:cirPulse 1.1s ease-in-out infinite;',
'}',
'',
'/* machine state */',
'.cmp-badge.ms-running { background:linear-gradient(180deg,#f0fdf4,#dcfce7); color:#15803d; border-color:#86efac; }',
'.cmp-badge.ms-stopped { background:linear-gradient(180deg,#fff1f1,#fee2e2); color:#b91c1c; border-color:#fca5a5; }',
'.cmp-badge.ms-stopped .cmp-dot { animation:cirPulse 1.1s ease-in-out infinite; }',
'.cmp-badge.ms-running .cmp-dot { box-shadow:0 0 0 3px rgba(34,197,94,.22); }',
'',
'/* status */',
'.cmp-badge[class*="st-"]  { background:#e8f1fb; color:#1f5f9f; border-color:#bfd7ee; }',
'.cmp-badge.st-open        { background:linear-gradient(180deg,#eff6ff,#dbeafe); color:#1d4ed8; border-color:#93c5fd; }',
'.cmp-badge.st-acknowledged{ background:linear-gradient(180deg,#fffbeb,#fef3c7); color:#b45309; border-color:#fcd34d; }',
'.cmp-badge.st-in-progress { background:linear-gradient(180deg,#f5f3ff,#ede9fe); color:#6d28d9; border-color:#c4b5fd; }',
'.cmp-badge.st-resolved    { background:linear-gradient(180deg,#f0fdf4,#dcfce7); color:#15803d; border-color:#86efac; }',
'.cmp-badge.st-rejected,',
'.cmp-badge.st-reopened    { background:linear-gradient(180deg,#fff1f1,#fee2e2); color:#b91c1c; border-color:#fca5a5; }',
'',
'/* =========================================================',
'   ANIMATIONS',
'   ========================================================= */',
'@keyframes cirIn   { from{opacity:0; transform:translateY(8px)} to{opacity:1; transform:none} }',
'@keyframes cirRow  { from{opacity:0; transform:translateX(-6px)} to{opacity:1; transform:none} }',
'@keyframes cirFlow { 0%{background-position:0 0} 100%{background-position:200% 0} }',
'@keyframes cirPulse{ 0%,100%{opacity:1; transform:scale(1)} 50%{opacity:.35; transform:scale(1.4)} }',
'@keyframes cirLive { 0%,100%{box-shadow:0 0 0 4px rgba(34,197,94,.18)} 50%{box-shadow:0 0 0 7px rgba(34,197,94,.06)} }',
'',
'@media (prefers-reduced-motion:reduce) {',
'    #COMPLAINT_IR, #COMPLAINT_IR::before, #COMPLAINT_IR .a-IRR-table tbody tr,',
'    .cmp-badge .cmp-dot, .cmp-badge.prio-critical::before,',
'    #COMPLAINT_IR .t-Region-title::before { animation:none !important; }',
'}',
'',
'/* =========================================================',
'   MOBILE',
'   ========================================================= */',
'@media (max-width:640px) {',
'    #COMPLAINT_IR { border-radius:14px; }',
'    #COMPLAINT_IR > .t-Region-header { padding:14px 16px 12px; }',
'    #COMPLAINT_IR .t-Region-title { font-size:16px; }',
'    #COMPLAINT_IR .a-IRR-toolbar { padding:10px 12px; }',
'    #COMPLAINT_IR .a-IRR-searchField:focus,',
'    #COMPLAINT_IR .a-IRR-toolbar input[type="text"]:focus { min-width:220px; }',
'    #COMPLAINT_IR .a-IRR-table td { padding:10px 8px; font-size:12px; }',
'    #COMPLAINT_IR .a-IRR-header { padding:11px 8px; font-size:10px; }',
'    #COMPLAINT_IR .a-IRR-tableContainer { max-height:60vh; }',
'}'))
,p_step_template=>wwv_flow_imp.id(384772671201539524)
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
