wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(387783619265779050)
,p_plug_name=>'Complain Register Report'
,p_region_name=>'COMPLAINT_IR'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(384804155185539590)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT H.COMPLAINT_ID,',
'       H.COMPLAINT_NO,',
'       TO_CHAR(H.COMPLAINT_DATE, ''DD-MON-YYYY HH12:MI AM'') AS COMPLAINT_DATE,',
'       H.REPORTED_BY,',
'       H.DEPARTMENT_ID,',
'       (SELECT EH.HALL_NAME',
'          FROM EM_HALLS EH',
'         WHERE EH.HALL_ID = H.DEPARTMENT_ID)               AS HALL_NAME,',
'       H.LINE_ID,',
'       (SELECT EM.MACHINE_NAME',
'          FROM EM_MACHINES EM',
'         WHERE EM.MACHINE_ID = H.MACHINE_ID)               AS MACHINE_NAME,',
'       (SELECT EF.FAULT_NAME',
'          FROM EM_MACHINE_FAULTS EF',
'         WHERE EF.MACHINE_FAULT_ID = H.FAULT_ID)           AS FAULT_NAME,',
'',
'       H.PRIORITY_ID,',
'       /* ADJUST mapping to your PRIORITY_ID values */',
'       CASE H.PRIORITY_ID',
'            WHEN 1 THEN ''<span class="cmp-badge prio-critical">Critical</span>''',
'            WHEN 2 THEN ''<span class="cmp-badge prio-high">High</span>''',
'            WHEN 3 THEN ''<span class="cmp-badge prio-medium">Medium</span>''',
'            WHEN 4 THEN ''<span class="cmp-badge prio-low">Low</span>''',
'            ELSE        ''<span class="cmp-badge prio-none">-</span>''',
'       END                                                 AS PRIORITY_BADGE,',
'',
'       H.FAULT_DESCRIPTION,',
'       H.PRODUCTION_IMPACT,',
'',
'       CASE WHEN H.MACHINE_STOPPED = ''N''',
'            THEN ''<span class="cmp-badge ms-running"><i class="cmp-dot"></i>RUNNING</span>''',
'            ELSE ''<span class="cmp-badge ms-stopped"><i class="cmp-dot"></i>STOPPED</span>''',
'       END                                                 AS MACHINE_STATE,',
'',
'       H.STATUS_CODE,',
'       ''<span class="cmp-badge st-''',
'         || LOWER(REGEXP_REPLACE(H.STATUS_CODE, ''[^A-Za-z0-9]'', ''-'')) || ''">''',
'         || APEX_ESCAPE.HTML(H.STATUS_CODE) || ''</span>''   AS STATUS_BADGE,',
'',
'       TO_CHAR(H.REPORTED_DATE_TIME,     ''DD-MON-YYYY HH12:MI AM'') AS REPORTED_DATE_TIME,',
'       TO_CHAR(H.ACKNOWLEDGED_DATE_TIME, ''DD-MON-YYYY HH12:MI AM'') AS ACKNOWLEDGED_DATE_TIME,',
'       TO_CHAR(H.RESOLVED_DATE_TIME,     ''DD-MON-YYYY HH12:MI AM'') AS RESOLVED_DATE_TIME,',
'       TO_CHAR(H.CLOSED_DATE_TIME,       ''DD-MON-YYYY HH12:MI AM'') AS CLOSED_DATE_TIME,',
'       H.DOWNTIME_MINUTES,',
'       H.REOPEN_COUNT,',
'       H.REJECTION_REASON,',
'       H.EXCEPTIONAL_CLOSURE',
'  FROM MS_COMPLAINT_H H',
'  WHERE H.STATUS_CODE NOT IN (''CLOSED'',''CANCELLED'')',
'  ORDER BY H.COMPLAINT_NO DESC',
'',
'',
'',
'-- select H.COMPLAINT_ID,',
'--        H.COMPLAINT_NO,',
'--        TO_CHAR(H.COMPLAINT_DATE, ''DD-MON-YYYY HH12:MI AM'') AS COMPLAINT_DATE,',
'--        H.REPORTED_BY,',
'--        H.DEPARTMENT_ID,',
'--          (SELECT EH.HALL_NAME ',
'--           FROM EM_HALLS EH',
'--           WHERE EH.HALL_ID=H.DEPARTMENT_ID) AS HALL_NAME,',
'--        H.LINE_ID,',
'--            (SELECT EM.MACHINE_NAME ',
'--             FROM EM_MACHINES EM',
'--             WHERE EM.MACHINE_ID=H.MACHINE_ID) AS MACHINE_NAME,',
'--            ( SELECT EF.FAULT_NAME ',
'--              FROM EM_MACHINE_FAULTS EF',
'--              WHERE EF.MACHINE_FAULT_ID=H.FAULT_ID ) AS FAULT_NAME,',
'--        H.PRIORITY_ID,',
'     ',
'--        H.FAULT_DESCRIPTION,',
'--        H.PRODUCTION_IMPACT,',
'--         CASE WHEN H.MACHINE_STOPPED = ''N'' THEN ''RUNNING''',
'--         ELSE ''STOPED''',
'--         END AS MACHINE_STOPPED,',
'--         H.STATUS_CODE,',
'--        TO_CHAR(H.REPORTED_DATE_TIME, ''DD-MON-YYYY HH12:MI AM'' ) AS REPORTED_DATE_TIME,',
'--        TO_CHAR(H.ACKNOWLEDGED_DATE_TIME, ''DD-MON-YYYY HH12:MI AM'' ) AS ACKNOWLEDGED_DATE_TIME,',
'--        TO_CHAR(H.RESOLVED_DATE_TIME, ''DD-MON-YYYY HH12:MI AM'' ) AS RESOLVED_DATE_TIME,',
'--        TO_CHAR(H.CLOSED_DATE_TIME, ''DD-MON-YYYY HH12:MI AM'' ) AS CLOSED_DATE_TIME,',
'--        H.DOWNTIME_MINUTES,',
'--        H.REOPEN_COUNT,',
'--        H.REJECTION_REASON,',
'--        H.EXCEPTIONAL_CLOSURE',
'--   from MS_COMPLAINT_H H',
'--   WHERE STATUS_CODE<>''CLOSED''',
'--   ORDER BY H.COMPLAINT_NO DESC',
'',
'',
'--   WHERE H.MACHINE_STOPPED <> ''N'''))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Complain Register Report'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#EEEEEE'
,p_prn_header_font_color=>'#000000'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'bold'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#FFFFFF'
,p_prn_body_font_color=>'#000000'
,p_prn_body_font_family=>'Helvetica'
,p_prn_body_font_weight=>'normal'
,p_prn_body_font_size=>'10'
,p_prn_border_width=>.5
,p_prn_page_header_alignment=>'CENTER'
,p_prn_page_footer_alignment=>'CENTER'
,p_prn_border_color=>'#666666'
);
wwv_flow_imp_page.create_worksheet(
