,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'/* STATIC FORM BUTTONS */',
'#COMP_FORM_REGION .t-Button,',
'#COMP_FORM_REGION button,',
'#COMP_FORM_REGION input[type="button"],',
'#COMP_FORM_REGION input[type="submit"] {',
'    border-radius: 999px !important;',
'    font-weight: 600 !important;',
'    font-size: 12.5px !important;',
'    padding: 8px 16px !important;',
'',
'    /* Preserve Original APEX Colors */',
'    transition: transform .15s ease,',
'                box-shadow .15s ease,',
'                filter .15s ease !important;',
'}',
'',
'/* BUTTON HOVER */',
'#COMP_FORM_REGION .t-Button:hover,',
'#COMP_FORM_REGION button:hover,',
'#COMP_FORM_REGION input[type="button"]:hover,',
'#COMP_FORM_REGION input[type="submit"]:hover {',
'    transform: translateY(-1px);',
'    filter: brightness(1.08);',
'    box-shadow: 0 4px 10px -4px rgba(11,18,32,.22);',
'}',
'',
'/* BUTTON ACTIVE */',
'#COMP_FORM_REGION .t-Button:active,',
'#COMP_FORM_REGION button:active {',
'    transform: translateY(0);',
'    filter: brightness(.96);',
'    box-shadow: none;',
'}',
'',
'/* -------------------------------------------------------------------------------------------------- */',
' ',
' /*DESING MSG CSS*/',
'',
'/* -------------------------------------------------------------------------------------------------- */',
'',
'/* =========================================================',
'   MMS PREMIUM FLOATING ALERT - V3',
'   Oracle APEX Universal Theme',
'   - Background blur while alert is visible',
'   - Alert + blur auto-hide after 3 seconds (--mms-show)',
'   - New design: light glass card, floating icon badge on top',
'========================================================= */',
'',
':root {',
'    --mms-show: 3s;        /* total time alert stays visible */',
'    --mms-exit: .5s;       /* fade-out duration at the end   */',
'    --mms-accent: 99, 102, 241;',
'}',
'',
'/* ===== Blur background (fades out with the alert) ===== */',
'body:has(.t-Body-alert .t-Alert)::before {',
'    content: "";',
'    position: fixed;',
'    inset: 0;',
'    z-index: 999998;',
'    background: rgba(15, 23, 42, .28);',
'    -webkit-backdrop-filter: blur(8px) saturate(120%);',
'    backdrop-filter: blur(8px) saturate(120%);',
'    pointer-events: none;',
'    animation:',
'        mmsBackdropIn .4s ease both,',
'        mmsBackdropOut var(--mms-exit) ease calc(var(--mms-show) - var(--mms-exit)) forwards;',
'}',
'',
'@keyframes mmsBackdropIn  { from { opacity: 0; } to { opacity: 1; } }',
'@keyframes mmsBackdropOut { from { opacity: 1; } to { opacity: 0; visibility: hidden; } }',
'',
'/* ===== Container (centered, auto-hides after 3s) ===== */',
'.t-Body-alert,',
'#t_Alert_Notification,',
'#t_Alert_Success {',
'    position: fixed !important;',
'    top: 50% !important;',
'    left: 50% !important;',
'    right: auto !important;',
'    translate: -50% -50% !important;',
'    width: min(420px, 90vw) !important;',
'    z-index: 999999 !important;',
'    overflow: visible !important;',
'    filter: drop-shadow(0 28px 50px rgba(15, 23, 42, .35));',
'    animation:',
'        mmsAlertEnter .6s cubic-bezier(.16, 1, .3, 1) both,',
'        mmsAlertExit var(--mms-exit) ease calc(var(--mms-show) - var(--mms-exit)) forwards;',
'}',
'',
'@keyframes mmsAlertEnter {',
'    0%   { opacity: 0; transform: translateY(40px) scale(.85); }',
'    65%  { opacity: 1; transform: translateY(-6px) scale(1.02); }',
'    100% { opacity: 1; transform: translateY(0) scale(1); }',
'}',
'',
'@keyframes mmsAlertExit {',
'    from { opacity: 1; transform: translateY(0) scale(1); }',
'    to   { opacity: 0; transform: translateY(-14px) scale(.94); visibility: hidden; }',
'}',
'',
'/* ===== Card ===== */',
'.t-Body-alert .t-Alert {',
'    position: relative !important;',
'    overflow: visible !important;',
'    border-radius: 24px !important;',
'    border: 1px solid rgba(255, 255, 255, .85) !important;',
'    background:',
'        radial-gradient(90% 70% at 50% 0%, rgba(var(--mms-accent), .14), transparent 70%),',
'        linear-gradient(180deg, rgba(255, 255, 255, .96), rgba(244, 246, 252, .92)) !important;',
'    -webkit-backdrop-filter: blur(20px);',
'    backdrop-filter: blur(20px);',
'    box-shadow:',
'        0 1px 0 rgba(255, 255, 255, 1) inset,',
'        0 0 0 1px rgba(var(--mms-accent), .12),',
'        0 18px 40px rgba(15, 23, 42, .18) !important;',
'    padding: 0 !important;',
'    color: #1e293b !important;',
'    margin-top: 0 !important;',
'}',
'',
'/* Colored top edge */',
'.t-Body-alert .t-Alert::before {',
'    content: "";',
'    position: absolute;',
'    top: 0;',
'    left: 28px;',
'    right: 28px;',
'    height: 3px;',
'    border-radius: 0 0 6px 6px;',
'    background: linear-gradient(90deg, transparent, rgb(var(--mms-accent)), transparent);',
'    pointer-events: none;',
'}',
'',
'/* ===== Layout: centered column, space for floating icon ===== */',
'.t-Body-alert .t-Alert-wrap {',
'    position: relative !important;',
'    display: flex !important;',
'    flex-direction: column !important;',
'    align-items: center !important;',
'    justify-content: center !important;',
'    text-align: center !important;',
'    min-height: 0;',
'    padding: 50px 30px 30px !important;',
'    overflow: visible !important;',
'}',
'',
'.t-Body-alert .t-Alert-content {',
'    padding: 0 !important;',
'    min-width: 0;',
'    width: 100%;',
'    animation: mmsTextIn .5s cubic-bezier(.16, 1, .3, 1) .15s both;',
'}',
'',
'@keyframes mmsTextIn {',
'    from { opacity: 0; transform: translateY(8px); }',
'    to   { opacity: 1; transform: translateY(0); }',
'}',
'',
'/* ===== Floating icon badge (half outside the card) ===== */',
'.t-Body-alert .t-Alert-icon {',
'    position: absolute !important;',
'    top: -34px !important;',
'    left: 50% !important;',
'    translate: -50% 0;',
'    width: 68px !important;',
'    height: 68px !important;',
'    margin: 0 !important;',
'    display: flex !important;',
'    align-items: center !important;',
'    justify-content: center !important;',
'    border-radius: 50% !important;',
'    background: linear-gradient(145deg, rgba(var(--mms-accent), 1), rgba(var(--mms-accent), .75)) !important;',
'    border: 5px solid #fff !important;',
'    box-shadow:',
'        0 10px 24px rgba(var(--mms-accent), .45),',
'        0 0 0 0 rgba(var(--mms-accent), .35);',
'    animation: mmsBadgePop .7s cubic-bezier(.34, 1.56, .64, 1) .1s both,',
'               mmsBadgeRing 2s ease-out .8s infinite;',
'}',
'',
'@keyframes mmsBadgePop {',
'    from { transform: scale(0) rotate(-40deg); }',
'    to   { transform: scale(1) rotate(0); }',
'}',
'',
'@keyframes mmsBadgeRing {',
'    0%   { box-shadow: 0 10px 24px rgba(var(--mms-accent), .45), 0 0 0 0 rgba(var(--mms-accent), .35); }',
'    80%, 100% { box-shadow: 0 10px 24px rgba(var(--mms-accent), .45), 0 0 0 16px rgba(var(--mms-accent), 0); }',
'}',
'',
'.t-Body-alert .t-Alert-icon .t-Icon {',
'    color: #fff !important;',
'    font-size: 28px !important;',
'    margin: 0 !important;',
'    filter: drop-shadow(0 2px 4px rgba(0, 0, 0, .2));',
'}',
'',
'/* ===== Title ===== */',
'.t-Body-alert .t-Alert-title {',
'    color: #0f172a !important;',
'    font-size: 18px !important;',
'    font-weight: 800 !important;',
'    letter-spacing: .2px;',
'    line-height: 1.35 !important;',
'    margin: 0 0 8px !important;',
'}',
'',
'/* ===== Message ===== */',
'.t-Body-alert .t-Alert-body,',
'.t-Body-alert .t-Alert-body * {',
'    color: #475569 !important;',
'    font-size: 14px !important;',
'    font-weight: 500 !important;',
'    line-height: 1.65 !important;',
'    overflow-wrap: anywhere;',
'}',
'',
'.t-Body-alert .t-Alert-body a {',
'    color: rgb(var(--mms-accent)) !important;',
'    font-weight: 700;',
'    text-decoration: underline;',
'    text-underline-offset: 3px;',
'}',
'',
'/* ===== Close button ===== */',
'.t-Body-alert .t-Button--closeAlert {',
'    position: absolute !important;',
'    top: 14px !important;',
'    right: 14px !important;',
'    z-index: 1000000 !important;',
'    display: flex !important;',
'    align-items: center !important;',
'    justify-content: center !important;',
'    width: 32px !important;',
'    min-width: 32px !important;',
'    height: 32px !important;',
'    min-height: 32px !important;',
'    padding: 0 !important;',
'    margin: 0 !important;',
'    border-radius: 50% !important;',
'    border: 1px solid rgba(15, 23, 42, .10) !important;',
'    background: rgba(15, 23, 42, .06) !important;',
'    color: #475569 !important;',
'    opacity: 1 !important;',
'    visibility: visible !important;',
'    cursor: pointer;',
'    box-shadow: none;',
'    transition: transform .3s cubic-bezier(.16, 1, .3, 1), background .25s ease, color .25s ease !important;',
'}',
'',
'.t-Body-alert .t-Button--closeAlert .t-Icon {',
'    color: inherit !important;',
'    font-size: 13px !important;',
'    font-weight: 900 !important;',
'    margin: 0 !important;',
'}',
'',
'.t-Body-alert .t-Button--closeAlert:hover {',
'    background: rgb(var(--mms-accent)) !important;',
'    color: #fff !important;',
'    transform: rotate(90deg) scale(1.08) !important;',
'}',
'',
'.t-Body-alert .t-Button--closeAlert:focus-visible {',
'    outline: 2px solid rgb(var(--mms-accent));',
'    outline-offset: 3px;',
'}',
'',
'/* ===== Types ===== */',
'.t-Body-alert .t-Alert--danger  { --mms-accent: 239, 68, 68; }',
'.t-Body-alert .t-Alert--success { --mms-accent: 16, 185, 129; }',
'.t-Body-alert .t-Alert--info    { --mms-accent: 59, 130, 246; }',
'.t-Body-alert .t-Alert--warning { --mms-accent: 245, 158, 11; }',
'',
'/* ===== 3-second progress bar ===== */',
'.t-Body-alert .t-Alert-wrap::after {',
'    content: "";',
'    position: absolute;',
'    left: 28px;',
'    right: 28px;',
'    bottom: 12px;',
'    height: 4px;',
'    border-radius: 10px;',
'    background: linear-gradient(90deg, rgba(var(--mms-accent), .55), rgb(var(--mms-accent)));',
'    transform-origin: left;',
'    animation: mmsAlertProgress var(--mms-show) linear forwards;',
'    pointer-events: none;',
'}',
'',
'@keyframes mmsAlertProgress {',
'    from { transform: scaleX(1); }',
'    to   { transform: scaleX(0); }',
'}',
'',
'/* ===== Mobile ===== */',
'@media (max-width: 600px) {',
'',
'    .t-Body-alert,',
'    #t_Alert_Notification,',
'    #t_Alert_Success {',
'        width: 92vw !important;',
'    }',
'',
'    .t-Body-alert .t-Alert { border-radius: 20px !important; }',
'',
'    .t-Body-alert .t-Alert-wrap {',
'        padding: 46px 22px 28px !important;',
'    }',
'',
'    .t-Body-alert .t-Alert-icon {',
'        width: 60px !important;',
'        height: 60px !important;',
'        top: -30px !important;',
'    }',
'',
'    .t-Body-alert .t-Alert-icon .t-Icon { font-size: 24px !important; }',
'    .t-Body-alert .t-Alert-title { font-size: 16px !important; }',
'',
'    .t-Body-alert .t-Alert-body,',
'    .t-Body-alert .t-Alert-body * { font-size: 13px !important; }',
'}',
'',
'/* =========================================================',
'   HOVER BEHAVIOR',
'   - Mouse on alert: timer, progress bar, blur and fade-out all PAUSE',
'   - Mouse leaves: everything resumes from where it stopped',
'   - Card lifts slightly, close button reacts',
'========================================================= */',
'.t-Body-alert,',
'#t_Alert_Notification,',
'#t_Alert_Success,',
'.t-Body-alert .t-Alert,',
'.t-Body-alert .t-Alert-wrap,',
'.t-Body-alert .t-Button--closeAlert {',
'    pointer-events: auto !important;',
'}',
'',
'.t-Body-alert:hover,',
'#t_Alert_Notification:hover,',
'#t_Alert_Success:hover,',
'.t-Body-alert:hover .t-Alert-wrap::after {',
'    animation-play-state: paused !important;',
'}',
'',
'body:has(.t-Body-alert:hover)::before {',
'    animation-play-state: paused !important;',
'}',
'',
'.t-Body-alert .t-Alert {',
'    transition: transform .35s cubic-bezier(.16, 1, .3, 1), box-shadow .35s ease !important;',
'}',
'',
'.t-Body-alert .t-Alert:hover {',
'    transform: translateY(-4px) !important;',
'    box-shadow:',
'        0 1px 0 rgba(255, 255, 255, 1) inset,',
'        0 0 0 1px rgba(var(--mms-accent), .30),',
'        0 26px 54px rgba(15, 23, 42, .26),',
'        0 0 34px rgba(var(--mms-accent), .22) !important;',
'}',
'',
'/* ===== Reduced motion (still auto-hides after 3s) ===== */',
'@media (prefers-reduced-motion: reduce) {',
'    .t-Body-alert .t-Alert-icon,',
'    .t-Body-alert .t-Alert-content {',
'        animation: none !important;',
'    }',
'}'))
