'    if (!hallId || isNaN(Number(hallId))) {',
'        apex.message.alert("Invalid Hall ID.");',
'        return;',
'    }',
'',
'    apex.server.process(',
'        "GET_LINES_URL",',
'        { x01: hallId },',
'        {',
'            dataType: "text",',
'            success: function (url) {',
'                apex.navigation.redirect(url);',
'            },',
'            error: function (jqXHR, textStatus, errorThrown) {',
'                apex.message.alert(',
'                    "Unable to open Lines page: " + errorThrown',
'                );',
'            }',
'        }',
'    );',
'}'))
