,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* =========================================',
'   MMS PREMIUM VALIDATION ERROR NOTIFICATION',
'========================================= */',
'',
'.t-Body-alert .t-Alert--danger,',
'#t_Alert_Notification .t-Alert--danger,',
'#t_Alert_Success .t-Alert--danger {',
'',
'    position: relative !important;',
