,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* Flex container to align buttons properly */',
'#P10_STATUS_CODE fieldset {',
'    display: flex;',
'    flex-wrap: wrap;',
'    gap: 5px;',
'    justify-content: center;',
'    border: none; /* Removes default APEX border */',
'    padding: 0;',
'    margin: 0;',
'}',
'',
'/* Style each fault button */',
'#P10_STATUS_CODE label {',
'    flex: 1 1 calc(25% - 5px); /* Adjust for 4 columns */',
'    max-width: 180px;',
'    background-color: #f8f9fa;',
'    border: 1px solid #ccc;',
'    padding: 12px;',
'    text-align: center;',
'    cursor: pointer;',
'    border-radius: 5px;',
'    font-weight: bold;',
'    transition: all 0.3s ease-in-out;',
'    display: flex;',
'    align-items: center;',
'    justify-content: center;',
'    min-height: 50px;',
'}',
